import test,{afterEach} from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {Window} from 'happy-dom';import React,{act} from 'react';import {createSurfaceSession,SurfaceRenderer} from '../src/index.ts';import {config,proposal,raw} from './fixture.ts';
const w=new Window({url:'http://localhost/'});for(const k of ['window','document','HTMLElement','HTMLButtonElement','Event','MouseEvent','KeyboardEvent'] as const)Object.defineProperty(globalThis,k,{configurable:true,value:k==='window'?w:w[k]});Object.defineProperty(globalThis,'navigator',{configurable:true,value:w.navigator});Object.assign(globalThis,{IS_REACT_ACT_ENVIRONMENT:true});const {createRoot}=await import('react-dom/client');let root:ReturnType<typeof createRoot>|null=null;let host:HTMLDivElement;let session:ReturnType<typeof createSurfaceSession>;let props:any;
async function render(extra:any={},p=proposal()){session=createSurfaceSession(config());session.submit(JSON.stringify(p));host=document.createElement('div');document.body.append(host);root=createRoot(host);props={session,data:new Map([['count',{kind:'metric',state:'known',value:0}]]),...extra};await act(async()=>root!.render(<SurfaceRenderer {...props}/>))}
const find=(s:string)=>{const e=host.querySelector(s);assert.ok(e,s);return e as HTMLElement};async function click(e:HTMLElement){await act(async()=>e.dispatchEvent(new w.MouseEvent('click',{bubbles:true}) as any))}
afterEach(async()=>{if(root)await act(async()=>root!.unmount());root=null;document.body.innerHTML=''});
test('untrusted labels and host provenance are visible, scripts stay escaped',async()=>{const p=proposal();p.components[1].props.text='<script>globalThis.hacked=true</script><img src=x onerror=evil()> APPROVED';await render({},p);assert.equal(host.querySelector('script,img,iframe'),null);assert.match(host.textContent??'',/<script>/);assert.match(host.textContent??'',/Vorgeschlagene Oberfläche/);assert.match(host.textContent??'',/Offline skill preview/);assert.match(host.textContent??'',/Ungeprüfter Vorschlag/);assert.equal((globalThis as any).hacked,undefined)});
test('unknown and stale host values differ from actual zero',async()=>{await render();assert.equal(find('[data-component-id="count"] [data-value]').textContent,'0');assert.match(find('[data-component-id="graph"]').textContent??'',/Datenstand unbekannt/);props.data=new Map([['count',{kind:'metric',state:'stale',value:7}]]);await act(async()=>root!.render(<SurfaceRenderer {...props}/>));assert.match(find('[data-component-id="count"]').textContent??'',/Veralteter/);props.data=new Map();await act(async()=>root!.render(<SurfaceRenderer {...props}/>));assert.match(find('[data-component-id="count"]').textContent??'',/Datenstand unbekannt/);assert.equal(host.querySelector('[data-value]'),null)});
test('actions are inert until native button activation, labels are host-owned and replay blocked',async()=>{const intents:any[]=[];await render({onIntent:(i:any)=>intents.push(i)});assert.equal(intents.length,0);const button=find('[data-action-ref="inspect"]');assert.equal(button.tagName,'BUTTON');assert.equal(button.getAttribute('type'),'button');assert.match(button.textContent??'',/Navigation: Aufgaben ansehen/);await click(button);await click(button);assert.equal(intents.length,1);assert.equal(intents[0].kind,'navigate');assert.equal(intents[0].componentId,'greeting')});
test('callback failures are caught, redacted and do not alter host data',async()=>{await render({onIntent:async()=>{throw new Error('SECRET-token')}});await click(find('[data-action-ref="inspect"]'));assert.match(host.textContent??'',/Übergabe fehlgeschlagen/);assert.doesNotMatch(host.textContent??'',/SECRET/);assert.equal(find('[data-value]').textContent,'0')});
test('layout updates preserve active button and invalid update retains last tree',async()=>{await render({onIntent:()=>{}});const button=find('[data-action-ref="inspect"]');button.focus();const p=proposal({baseRevision:1});p.components[0].props.layout='split';await act(async()=>session.submit(JSON.stringify(p)));assert.equal(document.activeElement,button);assert.equal(find('[data-layout]').getAttribute('data-layout'),'split');await act(async()=>session.submit(raw({baseRevision:1})));assert.equal(find('[data-layout]').getAttribute('data-layout'),'split');assert.match(host.textContent??'',/Aktualisierung abgelehnt/)});
test('removed focused component moves to surface host anchor',async()=>{await render({onIntent:()=>{}});find('[data-action-ref="inspect"]').focus();const p=proposal({baseRevision:1});p.components=p.components.filter((c:any)=>c.id!=='greeting');p.components[0].children=p.components[0].children.filter((id:string)=>id!=='greeting');await act(async()=>session.submit(JSON.stringify(p)));assert.equal(document.activeElement,find('[data-surface-anchor]'))});
test('hostslots only receive bound host data; absent slots explicit; throwing slots contained',async()=>{await render({data:new Map([['graph',{kind:'graph',state:'known',value:{nodes:['host-only']}}]]),slots:{Graph:({value}:any)=><p data-slot>{value.nodes[0]}</p>}});assert.equal(find('[data-slot]').textContent,'host-only');props.slots={};await act(async()=>root!.render(<SurfaceRenderer {...props}/>));assert.match(find('[data-component-id="graph"]').textContent??'',/Hostansicht nicht registriert/)});
test('mismatched malformed or oversized host projection rejects visibly',async()=>{await render({data:new Map([['count',{kind:'metric',state:'known',value:NaN}]])});assert.match(find('[data-component-id="count"]').textContent??'',/Hostdaten ungültig/)});
test('task/source/event lists have stable records, explicit empty state and no raw links',async()=>{const p=proposal();p.components=[{id:'root',type:'Group',props:{layout:'stack'},children:['tasks','sources','events']},...['tasks','sources','events'].map((id,i)=>({id,type:['TaskList','SourceList','EventList'][i],props:{label:id},dataRef:id}))];await render({data:new Map([['tasks',{kind:'tasks',state:'known',value:[]}],['sources',{kind:'sources',state:'known',value:[{id:'src1',label:'https://untrusted.example',detail:'Snapshot'}]}],['events',{kind:'events',state:'known',value:[{id:'event1',label:'Started',detail:'Retained event'}]}]])},p);assert.match(host.textContent??'',/Keine Einträge/);assert.equal(host.querySelector('a'),null);assert.equal(find('[data-row-id="event1"]').textContent,'StartedRetained event')});
test('CSS preserves relative font sizes, mobile wrapping and reduced motion',()=>{const css=readFileSync(new URL('../src/styles.css',import.meta.url),'utf8');assert.doesNotMatch(css,/font-size\s*:\s*[\d.]+px/);assert.match(css,/prefers-reduced-motion/);assert.match(css,/@media.*max-width/);assert.doesNotMatch(css,/position:\s*(fixed|absolute)/);assert.match(css,/overflow-wrap:\s*anywhere/)});
test('focus reparenting restores stable component action, with no automatic intent',async()=>{let count=0;await render({onIntent:()=>{count++}});find('[data-action-ref="inspect"]').focus();const p=proposal({baseRevision:1});p.components.push({id:'nested',type:'Group',props:{layout:'stack'},children:['greeting']});p.components[0].children=p.components[0].children.map((x:string)=>x==='greeting'?'nested':x);await act(async()=>session.submit(JSON.stringify(p)));assert.equal((document.activeElement as HTMLElement)?.dataset.actionRef,'inspect');assert.equal(count,0)});
test('external host focus is never stolen during updates',async()=>{await render({onIntent:()=>{}});find('[data-action-ref="inspect"]').focus();const outside=document.createElement('button');document.body.append(outside);outside.focus();await act(async()=>session.submit(raw({baseRevision:1})));assert.equal(document.activeElement,outside)});
test('trusted slot render failure leaves provenance and other components usable',async()=>{const previous=console.error;let caught=0;console.error=()=>{caught++};try{await render({data:new Map([['graph',{kind:'graph',state:'known',value:{}}]]),slots:{Graph:()=>{throw Error('private host fault')}}});assert.match(host.textContent??'',/Hostansicht fehlgeschlagen/);assert.match(host.textContent??'',/Vorgeschlagene Oberfläche/);assert.doesNotMatch(host.textContent??'',/private host fault/);assert.ok(caught>0)}finally{console.error=previous}});
test('known lists reject duplicate identities and exceeding row limits visibly',async()=>{const p=proposal();p.components[2]={id:'count',type:'TaskList',props:{label:'Tasks'},dataRef:'count'};await render({data:new Map([['count',{kind:'tasks',state:'known',value:[{id:'a',label:'A'},{id:'a',label:'B'}]}]])},p);assert.match(host.textContent??'',/Hostdaten ungültig/);props.data=new Map([['count',{kind:'tasks',state:'known',value:Array.from({length:201},(_,i)=>({id:String(i),label:'Row'}))}]]);await act(async()=>root!.render(<SurfaceRenderer {...props}/>));assert.match(host.textContent??'',/Hostdaten ungültig/);assert.equal(host.querySelectorAll('[data-row-id]').length,0)});
test('root text enlargement preserves primary button scale in simulated CSS',async()=>{const style=document.createElement('style');style.textContent=readFileSync(new URL('../src/styles.css',import.meta.url),'utf8');document.head.append(style);try{await render();document.documentElement.style.fontSize='16px';const normal=parseFloat(w.getComputedStyle(find('button') as any).fontSize);document.documentElement.style.fontSize='24px';const enlarged=parseFloat(w.getComputedStyle(find('button') as any).fontSize);assert.equal(enlarged/normal,1.5)}finally{style.remove();document.documentElement.style.fontSize=''}});
test('pending intent cannot be reactivated when a newer layout revision arrives',async()=>{let release!:()=>void;let calls=0;await render({onIntent:()=>{calls++;return new Promise<void>(resolve=>{release=resolve})}});const button=find('[data-action-ref="inspect"]') as HTMLButtonElement;await click(button);assert.equal(button.disabled,true);await act(async()=>session.submit(raw({baseRevision:1})));assert.equal(button.disabled,true);await click(button);assert.equal(calls,1);await act(async()=>release());assert.equal(button.disabled,false);assert.doesNotMatch(host.textContent??'',/Intent an Host übergeben/)});
test('review R1 pending delivery survives reparenting then remove and readd',async()=>{let release!:()=>void;let calls=0;await render({onIntent:()=>{calls++;return new Promise<void>(r=>{release=r})}});await click(find('[data-action-ref="inspect"]'));const p=proposal({baseRevision:1});p.components.push({id:'nested',type:'Group',props:{layout:'stack'},children:['greeting']});p.components[0].children=p.components[0].children.map((id:string)=>id==='greeting'?'nested':id);await act(async()=>session.submit(JSON.stringify(p)));let button=find('[data-action-ref="inspect"]') as HTMLButtonElement;assert.equal(button.disabled,true);await click(button);assert.equal(calls,1);const removed=proposal({baseRevision:2});removed.components=removed.components.filter((c:any)=>c.id!=='greeting');removed.components[0].children=removed.components[0].children.filter((id:string)=>id!=='greeting');await act(async()=>session.submit(JSON.stringify(removed)));await act(async()=>session.submit(raw({baseRevision:3})));button=find('[data-action-ref="inspect"]') as HTMLButtonElement;assert.equal(button.disabled,true);assert.equal(button.getAttribute('aria-busy'),'true');await click(button);assert.equal(calls,1);await act(async()=>release());assert.equal(button.disabled,false);await click(button);assert.equal(calls,2);await act(async()=>release())});
test('review R2 pending status persists across revisions and clears after old delivery settles',async()=>{let release!:()=>void;await render({onIntent:()=>new Promise<void>(r=>{release=r})});await click(find('[data-action-ref="inspect"]'));await act(async()=>session.submit(raw({baseRevision:1})));assert.equal(find('[data-action-ref="inspect"]').getAttribute('aria-busy'),'true');assert.match(host.textContent??'',/Übergabe läuft/);await act(async()=>release());assert.equal(find('[data-action-ref="inspect"]').getAttribute('aria-busy'),'false');assert.doesNotMatch(host.textContent??'',/Übergabe läuft|Intent an Host übergeben/)});
test('review R3 corrected host data and fresh revision each reset a failed stable slot',async()=>{const previous=console.error;console.error=()=>{};try{const Graph=({value,surfaceRevision}:any)=>{if(value.broken||surfaceRevision===2)throw Error('private fault');return <p data-recovered>Recovered</p>};await render({data:new Map([['graph',{kind:'graph',state:'known',value:{broken:true}}]]),slots:{Graph}});assert.match(host.textContent??'',/Hostansicht fehlgeschlagen/);props.data=new Map([['graph',{kind:'graph',state:'known',value:{broken:false}}]]);await act(async()=>root!.render(<SurfaceRenderer {...props}/>));assert.equal(find('[data-recovered]').textContent,'Recovered');await act(async()=>session.submit(raw({baseRevision:1})));assert.match(host.textContent??'',/Hostansicht fehlgeschlagen/);await act(async()=>session.submit(raw({baseRevision:2})));assert.equal(find('[data-recovered]').textContent,'Recovered')}finally{console.error=previous}});
test('review R1 remount of whole renderer retains session pending delivery and safely settles after unmount',async()=>{let release!:()=>void;let calls=0;await render({onIntent:()=>{calls++;return new Promise<void>(r=>{release=r})}});await click(find('[data-action-ref="inspect"]'));await act(async()=>root!.unmount());root=createRoot(host);await act(async()=>session.submit(raw({baseRevision:1})));await act(async()=>root!.render(<SurfaceRenderer {...props}/>));const button=find('[data-action-ref="inspect"]') as HTMLButtonElement;assert.equal(button.disabled,true);await click(button);assert.equal(calls,1);await act(async()=>root!.unmount());root=null;await act(async()=>release());root=createRoot(host);await act(async()=>root!.render(<SurfaceRenderer {...props}/>));assert.equal((find('[data-action-ref="inspect"]') as HTMLButtonElement).disabled,false)});
